#define SIZE 8
static volatile uint8_t buf[SIZE];
static volatile uint8_t head = 0, tail = 0;

int push(uint8_t c) {              /* ISR se call */
    uint8_t next = (head + 1) % SIZE;
    if (next == tail) return 0;    /* full */
    buf[head] = c;
    head = next;
    return 1;
}

int pop(uint8_t *c) {              /* main se call */
    if (head == tail) return 0;    /* empty */
    *c = buf[tail];
    tail = (tail + 1) % SIZE;
    return 1;
}

