typedef enum { IDLE, RUNNING, PAUSED } state_t;
state_t s = IDLE;

void on_event(char e) {
    switch (s) {
    case IDLE:
        if (e == 'S') s = RUNNING;
        break;
    case RUNNING:
        if (e == 'P') s = PAUSED;
        else if (e == 'X') s = IDLE;
        break;
    case PAUSED:
        if (e == 'S') s = RUNNING;
        else if (e == 'X') s = IDLE;
        break;
    }
}

